n = int(d[0]); c = [0] + [int(v) for v in d[1:n + 1]]
X = 0
for i in range(1, n + 1, 2):
    X ^= c[i]
if X == 0:
    print("Bob")
else:
    w = 0
    for i in range(1, n + 1):
        if i % 2 == 1:
            if c[i] ^ X < c[i]: w += 1
        else:
            need = (c[i - 1] ^ X) - c[i - 1]
            if 0 < need <= c[i]: w += 1
    print("Alice", w)

