import sys
def main():
    d = list(map(int, sys.stdin.buffer.read().split())); n = d[0]
    S = [tuple(d[1 + 4 * i:5 + 4 * i]) for i in range(n)]
    def orient(ax, ay, bx, by, cx, cy):
        v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
        return (v > 0) - (v < 0)
    def onseg(ax, ay, bx, by, cx, cy):
        return min(ax, bx) <= cx <= max(ax, bx) and min(ay, by) <= cy <= max(ay, by)
    cnt = 0
    for i in range(n):
        ax, ay, bx, by = S[i]
        for j in range(i + 1, n):
            cx, cy, dx, dy = S[j]
            if max(ax, bx) < min(cx, dx) or max(cx, dx) < min(ax, bx) or max(ay, by) < min(cy, dy) or max(cy, dy) < min(ay, by):
                continue
            o1 = orient(ax, ay, bx, by, cx, cy); o2 = orient(ax, ay, bx, by, dx, dy)
            o3 = orient(cx, cy, dx, dy, ax, ay); o4 = orient(cx, cy, dx, dy, bx, by)
            if o1 * o2 < 0 and o3 * o4 < 0:
                cnt += 1
            elif (o1 == 0 and onseg(ax, ay, bx, by, cx, cy)) or (o2 == 0 and onseg(ax, ay, bx, by, dx, dy)) or \
                 (o3 == 0 and onseg(cx, cy, dx, dy, ax, ay)) or (o4 == 0 and onseg(cx, cy, dx, dy, bx, by)):
                cnt += 1
    print(cnt)
main()

import sys
def main():
    d = sys.stdin.buffer.read().split(); n = int(d[0])
    pts = sorted(set(zip(map(int, d[1:2 * n + 1:2]), map(int, d[2:2 * n + 2:2]))))
    if len(pts) == 1:
        print(0); return
    def build(seq):
        h = []
        for p in seq:
            while len(h) >= 2:
                o, a = h[-2], h[-1]
                if (a[0] - o[0]) * (p[1] - o[1]) - (a[1] - o[1]) * (p[0] - o[0]) <= 0: h.pop()
                else: break
            h.append(p)
        return h
    h = build(pts)[:-1] + build(pts[::-1])[:-1]
    m = len(h)
    def d2(a, b): return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
    if m == 2:
        print(d2(h[0], h[1])); return
    def area(a, b, c): return abs((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]))
    best = 0; j = 1
    for i in range(m):
        ni = (i + 1) % m
        while area(h[i], h[ni], h[(j + 1) % m]) > area(h[i], h[ni], h[j]):
            j = (j + 1) % m
        v = max(d2(h[i], h[j]), d2(h[ni], h[j]))
        if v > best: best = v
    print(best)
main()

