import sys
def main():
    d = sys.stdin.buffer.read().split()
    n, k = int(d[0]), int(d[1])
    S = sorted(set(int(v) for v in d[2:2 + k])); M = S[-1]
    a = [int(v) for v in d[2 + k:2 + k + n]]
    g = []; seen = {}
    x = 0
    while True:
        if x >= M:
            w = tuple(g[x - M:x])
            if w in seen:
                start = seen[w]; per = x - start; break
            seen[w] = x
        s = {g[x - t] for t in S if t <= x}
        v = 0
        while v in s: v += 1
        g.append(v); x += 1
    def G(v):
        return g[v] if v < len(g) else g[start + (v - start) % per]
    X = 0
    for v in a: X ^= G(v)
    if X == 0:
        print("Bob"); return
    w = 0
    for v in a:
        target = G(v) ^ X
        for t in S:
            if t <= v and G(v - t) == target: w += 1
    print("Alice", w)
main()
